<template>
  <div class="blog-list">
    <h2>{{ $t('blog.title') }}</h2>

    <div class="topic-filter">
      <button
        class="filter-button"
        :class="{ active: selectedTopic === '' }"
        @click="selectedTopic = ''"
      >
        {{ $t('common.all') }}
      </button>
      <button
        v-for="topic in topics"
        :key="topic"
        :class="['filter-button', { active: selectedTopic === topic }]"
        @click="toggleTopic(topic)"
      >
        {{ $t(`blog.topics.${topic}`) }}
      </button>
    </div>

    <ul v-if="filteredArticles.length">
      <li v-for="article in filteredArticles" :key="article.slug">
        <router-link :to="`/blog/${article.slug}`" class="article-card">
          <div class="topics">
            <span class="topic" v-for="topic in article.topics" :key="topic">{{ $t(`blog.topics.${topic}`) }}</span>
          </div>
          <h3>{{ article.title }}</h3>
          <div class="meta">{{ $t('blog.publishedOn') }} {{ article.date }}</div>
          <div class="tags">
            <span class="tag" v-for="tag in article.tags" :key="tag">{{ tag }}</span>
          </div>
          <p class="excerpt">{{ article.excerpt }}</p>
          <span class="read-more">{{ $t('blog.readMore') }} →</span>
        </router-link>
      </li>
    </ul>
    <p v-else class="no-results">{{ $t('blog.noResults') }}</p>
  </div>
</template>

<script>
import { getArticleList, TOPICS } from '../utils/articles'

export default {
  name: 'BlogList',
  data() {
    return {
      selectedTopic: ''
    }
  },
  computed: {
    topics() {
      return TOPICS
    },
    articles() {
      return getArticleList(this.$i18n.locale)
    },
    filteredArticles() {
      const query = (this.$route.query.q || '').trim().toLowerCase()
      return this.articles.filter((article) => {
        const matchesTopic = !this.selectedTopic || article.topics.includes(this.selectedTopic)
        const matchesSearch =
          !query ||
          article.tags.some((tag) => tag.toLowerCase().includes(query)) ||
          article.title.toLowerCase().includes(query)
        return matchesTopic && matchesSearch
      })
    }
  },
  methods: {
    toggleTopic(topic) {
      this.selectedTopic = this.selectedTopic === topic ? '' : topic
    }
  }
}
</script>

