// Auto-detects markdown paragraphs that are just a single character repeated
// (optionally separated by spaces) — e.g. "♗♗♗♗♗♗♗♗♗♗" or "✦ ✦ ✦ ✦ ✦ ✦ ✦" —
// and marks them as custom dividers so they can be styled (and sized
// differently for mobile vs desktop) via CSS, instead of rendering as a
// plain <p>.
const MIN_DIVIDER_LENGTH = 5

export function markDividers(html) {
  return html.replace(/<p>([^<]*)<\/p>/g, (match, inner) => {
    const compact = inner.replace(/\s+/g, '')
    const chars = [...compact]
    if (chars.length < MIN_DIVIDER_LENGTH) return match

    const unique = new Set(chars)
    if (unique.size !== 1) return match

    return `<p class="divider">${inner}</p>`
  })
}
