import MarkdownIt from 'markdown-it'
import { parseFrontmatter } from './frontmatter'
import { markDividers } from './dividers'

const md = new MarkdownIt({ html: false, linkify: true })

// Fixed set of topic tags (1-2 per article, used for filtering).
// Personal tags (in frontmatter's `tags` field) are free-form and used for search instead.
export const TOPICS = ['Experience', 'Learning', 'Community']

const files = require.context('../content/articles', false, /\.md$/)

const articlesByLocale = { en: {}, zh: {} }

files.keys().forEach((key) => {
  const name = key.replace('./', '').replace(/\.md$/, '')
  const [slug, locale] = name.split('.')
  const targetLocale = locale === 'zh' ? 'zh' : 'en'

  const rawModule = files(key)
  const raw = typeof rawModule === 'string' ? rawModule : rawModule.default || rawModule

  const { data, content } = parseFrontmatter(raw)
  articlesByLocale[targetLocale][slug] = {
    slug,
    title: data.title || slug,
    date: data.date || '',
    topics: (data.topics || []).filter((topic) => TOPICS.includes(topic)),
    tags: data.tags || [],
    excerpt: data.excerpt || '',
    html: markDividers(md.render(content))
  }
})

export function getArticleList(locale) {
  const localeMap = articlesByLocale[locale] || articlesByLocale.en
  const fallbackMap = articlesByLocale.en
  const slugs = new Set([...Object.keys(fallbackMap), ...Object.keys(localeMap)])
  return Array.from(slugs)
    .map((slug) => localeMap[slug] || fallbackMap[slug])
    .sort((a, b) => (a.date < b.date ? 1 : -1))
}

export function getArticle(slug, locale) {
  const localeMap = articlesByLocale[locale] || articlesByLocale.en
  return localeMap[slug] || articlesByLocale.en[slug] || null
}

