<template>
  <div class="header" id="header">
    <div class="header-search">
      <svg class="search-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
        <circle cx="11" cy="11" r="8"></circle>
        <line x1="21" y1="21" x2="16.65" y2="16.65"></line>
      </svg>
      <input
        v-model="searchInput"
        type="search"
        class="search-input"
        :placeholder="$t('blog.searchPlaceholder')"
        @input="onSearchInput"
      />
    </div>
    <div class="menu">
      <router-link to="/blog" class="nav-link">{{ $t('nav.blog') }}</router-link>
      <router-link to="/" class="nav-link">{{ $t('nav.about') }}</router-link>
      <button class="lang-toggle" @click="toggleLocale">{{ otherLocaleLabel }}</button>
    </div>
  </div>
</template>

<script>
import { setLocale } from '../i18n'

export default {
  name: 'MyHeader',
  data() {
    return {
      searchInput: this.$route.query.q || '',
      searchDebounce: null
    }
  },
  computed: {
    otherLocaleLabel() {
      return this.$i18n.locale === 'en' ? '中文' : 'EN'
    }
  },
  watch: {
    '$route.query.q'(value) {
      this.searchInput = value || ''
    }
  },
  mounted() {
    const header = document.getElementById('header');

    window.addEventListener('scroll', function() {
      if (window.scrollY > 100) {
        header.style.height = '50px';
      } else {
        header.style.height = '60px';
      }
    });
  },
  beforeUnmount() {
    clearTimeout(this.searchDebounce);
  },
  methods: {
    toggleLocale() {
      setLocale(this.$i18n.locale === 'en' ? 'zh' : 'en')
    },
    onSearchInput() {
      clearTimeout(this.searchDebounce);
      this.searchDebounce = setTimeout(() => {
        const query = this.searchInput.trim();
        const dest = { path: '/blog', query: query ? { q: query } : {} };
        if (this.$route.path === '/blog') {
          this.$router.replace(dest);
        } else {
          this.$router.push(dest);
        }
      }, 250);
    }
  }
}
</script>

